pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint16 feeRate, address baseToken, address nft, uint128 virtualBase, uint128 virtualNft, uint56 changeFee, bytes32 merkleRoot, bool useStolen, bool payRoyalties) public {
        feeRate = feeRate % 10001;

        bool ok;
        try c.initialize(baseToken, nft, virtualBase, virtualNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.feeRate() == feeRate, "feeRate should equal the _feeRate parameter when initialize succeeds");
        } else {
            return;
        }
    }
}
